const RepMedia=(()=>{
 async function photo(file){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('请选择 JPG、PNG 或 WebP 照片');
  if(file.size>10*1024*1024)throw new Error('照片需小于 10 MB');
  const url=URL.createObjectURL(file);let image;
  try{image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('照片无法读取'));img.src=url;});}finally{URL.revokeObjectURL(url);}
  const w=image.naturalWidth,h=image.naturalHeight;
  const canvas=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(w,h));canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#f0f6ed';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);
  const face='录入检查完成，请确认使用本人照片';
  return {data:canvas.toDataURL('image/jpeg',.86),width:w,height:h,report:`${w} × ${h} · 照片录入检查完成`,face};
 }
 function audioReport(buffer){const duration=buffer.duration;if(!Number.isFinite(duration)||duration<.2)throw new Error('未读取到有效录音，请重新采集');if(duration>90)throw new Error('录音请控制在 90 秒以内');return {duration,report:`${Math.round(duration)} 秒 · 声音录入检查完成`};}
 async function audio(blob){if(!blob||blob.size>20*1024*1024)throw new Error('录音文件需小于 20 MB');const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw new Error('当前浏览器无法分析录音，请使用新版 Safari 或 Chrome');const context=new Context();try{const buffer=await context.decodeAudioData(await blob.arrayBuffer());return audioReport(buffer);}catch(e){if(e instanceof DOMException)throw new Error('录音格式无法解析，请重录或上传 MP3、WAV、M4A');throw e;}finally{await context.close();}}
 let session;
 async function start(onEnd,onTick){if(session)throw new Error('请先结束当前录音');if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('当前浏览器不支持录音，请上传录音文件');const stream=await navigator.mediaDevices.getUserMedia({audio:true});let recorder;try{recorder=new MediaRecorder(stream);}catch(e){stream.getTracks().forEach(t=>t.stop());throw e;}const chunks=[],started=Date.now();const current={stream,recorder,cancel:false,timer:null};session=current;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{clearInterval(current.timer);stream.getTracks().forEach(t=>t.stop());if(session===current)session=null;if(!current.cancel)onEnd(new Blob(chunks,{type:recorder.mimeType}));};recorder.onerror=()=>{current.cancel=true;stop(true);};recorder.start();current.timer=setInterval(()=>{const seconds=Math.floor((Date.now()-started)/1000);onTick(seconds);if(seconds>=90)stop();},250);return true;}
 function stop(cancel=false){if(session){session.cancel=cancel;clearInterval(session.timer);session.stream.getTracks().forEach(t=>t.stop());if(session.recorder.state!=='inactive')session.recorder.stop();}}
 async function video(profile,narration,script,onProgress,signal){
  if(!window.MediaRecorder)throw new Error('当前浏览器不支持视频生成，请使用新版 Chrome 或 Safari');
  const canvas=document.createElement('canvas');canvas.width=540;canvas.height=720;if(!canvas.captureStream)throw new Error('当前浏览器不支持画面录制');
  const image=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('形象照片无法读取'));i.src=profile.photo;});
  const Context=window.AudioContext||window.webkitAudioContext,context=new Context();let stream,recorder,frame,timer;
  try{await context.resume();const buffer=await context.decodeAudioData(await narration.arrayBuffer());if(signal.aborted)throw new Error('已取消生成');const source=context.createBufferSource();source.buffer=buffer;const dest=context.createMediaStreamDestination();source.connect(dest);stream=canvas.captureStream(24);dest.stream.getAudioTracks().forEach(t=>stream.addTrack(t));const mime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/mp4','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw new Error('当前浏览器没有可用的视频编码器');recorder=new MediaRecorder(stream,{mimeType:mime});const ctx=canvas.getContext('2d'),started=performance.now();const draw=()=>{const elapsed=(performance.now()-started)/1000,p=Math.min(1,elapsed/buffer.duration);const scale=Math.max(540/image.width,720/image.height)*(1+.025*Math.sin(elapsed*.65));const w=image.width*scale,h=image.height*scale;ctx.drawImage(image,(540-w)/2,(720-h)/2,w,h);const shade=ctx.createLinearGradient(0,390,0,720);shade.addColorStop(0,'#173e3000');shade.addColorStop(1,'#173e30ee');ctx.fillStyle=shade;ctx.fillRect(0,0,540,720);ctx.fillStyle='#fff';ctx.font='600 28px sans-serif';ctx.fillText(profile.name+' · 医药代表',30,558);ctx.font='23px sans-serif';const lines=script.match(/.{1,20}/gu)||[];const line=Math.min(Math.floor(p*lines.length),Math.max(0,lines.length-1));ctx.fillText(lines[line]||'',30,608);ctx.fillStyle='#ffffff55';ctx.fillRect(30,675,480,4);ctx.fillStyle='#d0f0ce';ctx.fillRect(30,675,480*p,4);onProgress(Math.round(p*100));frame=requestAnimationFrame(draw);};draw();
   return await new Promise((resolve,reject)=>{const chunks=[];let done=false;const finish=error=>{if(done)return;done=true;clearTimeout(timer);signal.removeEventListener('abort',abort);try{source.stop();}catch{}if(error){if(recorder.state!=='inactive')recorder.stop();reject(error);}else if(recorder.state!=='inactive')recorder.stop();};const abort=()=>finish(new Error('已取消生成'));signal.addEventListener('abort',abort,{once:true});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>finish(new Error('视频生成失败，请重试'));recorder.onstop=()=>{if(chunks.length)resolve(new Blob(chunks,{type:mime}));else reject(new Error('视频未能生成，请重试'));};source.onended=()=>finish();recorder.start(300);source.start();timer=setTimeout(()=>finish(),buffer.duration*1000+1500);});
  }finally{clearTimeout(timer);cancelAnimationFrame(frame);stream?.getTracks().forEach(t=>t.stop());await context.close();}
 }
 return {photo,audio,audioReport,start,stop,video};
})();
